/**
 * Virtual project ids for automation task output directories.
 *
 * A task's artifacts live in `~/.fello/automations/<scheduleId>/tasks/<taskId>/`.
 * Exposing that directory as a virtual project lets the shared file panel / file
 * detail address it with the same `projectId` + relative path API as a real
 * project, without adding it to the sidebar project list.
 */
export const TASK_PROJECT_PREFIX = "__task__";

/**
 * Schedule / task ids are generated by Fello (`<timestamp>-<random>` and
 * `<timestamp>`), and are also used as path segments. Reject anything that could
 * escape the automations directory when an id arrives from IPC / a WebUI URL.
 */
// No `__` so the virtual-project id stays unambiguous when parsed back.
const SAFE_AUTOMATION_ID = /^(?!.*__)[A-Za-z0-9_-]+$/;

export function isSafeAutomationId(id: string): boolean {
  return SAFE_AUTOMATION_ID.test(id);
}

/** `__task__<scheduleId>__<taskId>__` */
export function taskProjectId(scheduleId: string, taskId: string): string {
  if (!isSafeAutomationId(scheduleId) || !isSafeAutomationId(taskId)) {
    throw new Error("Invalid task project id.");
  }
  return `${TASK_PROJECT_PREFIX}${scheduleId}__${taskId}__`;
}

/** Extracts the schedule / task ids, or null when the id is invalid/not a task project. */
export function parseTaskProjectId(
  projectId: string,
): { scheduleId: string; taskId: string } | null {
  if (!projectId.startsWith(TASK_PROJECT_PREFIX) || !projectId.endsWith("__")) return null;
  const body = projectId.slice(TASK_PROJECT_PREFIX.length, -2);
  const separator = body.lastIndexOf("__");
  if (separator <= 0) return null;
  const scheduleId = body.slice(0, separator);
  const taskId = body.slice(separator + 2);
  if (!isSafeAutomationId(scheduleId) || !isSafeAutomationId(taskId)) return null;
  return { scheduleId, taskId };
}
